-- Ruins of Ahn'Qiraj (map 509): about half of the raid's spawns were missing, among them every wave of General Rajaxx's
-- encounter. Spawns from the 5.4.8 data on new guids (creatures 9200000 to 9219999, objects 1050000 to 1054999), for the
-- creatures the map had fewer of, skipping spawns already present within 3 yards and game event spawns.
-- Safe to run twice (every block deletes its own range first).

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` BETWEEN -9219999 AND -9200000;
DELETE FROM `waypoint_data` WHERE `id` BETWEEN 92000000 AND 92199999;
DELETE FROM `creature_formations` WHERE `memberGUID` BETWEEN 9200000 AND 9219999;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 9200000 AND 9219999;
DELETE FROM `pool_creature` WHERE `guid` BETWEEN 9200000 AND 9219999;
DELETE FROM `pool_gameobject` WHERE `guid` BETWEEN 1050000 AND 1054999;
DELETE FROM `pool_pool` WHERE `pool_id` BETWEEN 320000 AND 321999;
DELETE FROM `pool_template` WHERE `entry` BETWEEN 320000 AND 321999;
DELETE FROM `creature` WHERE `guid` BETWEEN 9200000 AND 9219999;
DELETE FROM `gameobject` WHERE `guid` BETWEEN 1050000 AND 1054999;

